'use strict';

// MODULES //

var tape = require( 'tape' );
var isnan = require( '@stdlib/math/base/assert/is-nan' );
var isAlmostSameValue = require( '@stdlib/assert/is-almost-same-value' );
var PINF = require( '@stdlib/constants/float64/pinf' );
var NINF = require( '@stdlib/constants/float64/ninf' );
var entropy = require( './../lib' );


// FIXTURES //

var data = require( './fixtures/julia/data.json' );


// TESTS //

tape( 'main export is a function', function test( t ) {
	t.ok( true, __filename );
	t.strictEqual( typeof entropy, 'function', 'main export is a function' );
	t.end();
});

tape( 'if provided `NaN` for any parameter, the function returns `NaN`', function test( t ) {
	var y = entropy( NaN, 3.0 );
	t.strictEqual( isnan( y ), true, 'returns expected value' );
	y = entropy( 1.0, NaN );
	t.strictEqual( isnan( y ), true, 'returns expected value' );
	t.end();
});

tape( 'if provided a nonpositive `alpha`, the function returns `NaN`', function test( t ) {
	var y;

	y = entropy( 0.0, 3.0 );
	t.strictEqual( isnan( y ), true, 'returns expected value' );

	y = entropy( -1.0, 3.0 );
	t.strictEqual( isnan( y ), true, 'returns expected value' );

	y = entropy( NINF, 3.0 );
	t.strictEqual( isnan( y ), true, 'returns expected value' );

	t.end();
});

tape( 'if provided a nonpositive `beta`, the function returns `NaN`', function test( t ) {
	var y;

	y = entropy( 2.0, 0.0 );
	t.strictEqual( isnan( y ), true, 'returns expected value' );

	y = entropy( 2.0, -1.0 );
	t.strictEqual( isnan( y ), true, 'returns expected value' );

	y = entropy( 1.0, NINF );
	t.strictEqual( isnan( y ), true, 'returns expected value' );

	y = entropy( PINF, NINF );
	t.strictEqual( isnan( y ), true, 'returns expected value' );

	y = entropy( NINF, NINF );
	t.strictEqual( isnan( y ), true, 'returns expected value' );

	y = entropy( NaN, NINF );
	t.strictEqual( isnan( y ), true, 'returns expected value' );

	t.end();
});

tape( 'the function returns the differential entropy of a log-logistic distribution', function test( t ) {
	var expected;
	var alpha;
	var beta;
	var y;
	var i;

	expected = data.expected;
	alpha = data.alpha;
	beta = data.beta;
	for ( i = 0; i < alpha.length; i++ ) {
		y = entropy( alpha[ i ], beta[ i ] );
		t.strictEqual( isAlmostSameValue( y, expected[ i ], 1 ), true, 'returns expected value' );
	}
	t.end();
});
